function twoSumSorted(a, target) {
  const pairs = [];
  let lo = 0, hi = a.length - 1;

  while (lo < hi) {
    const sum = a[lo] + a[hi];
    if (sum === target) {
      pairs.push([a[lo], a[hi]]);
      lo++; hi--;
      while (lo < hi && a[lo] === a[lo - 1]) lo++;   // skip duplicate lefts
      while (lo < hi && a[hi] === a[hi + 1]) hi--;   // skip duplicate rights
    } else if (sum < target) {
      lo++;
    } else {
      hi--;
    }
  }
  return pairs;
}

