bool isPalindromeSentence(const std::string& s) {
    int lo = 0, hi = (int)s.size() - 1;

    while (lo < hi) {
        // Each pointer skips on its own.
        if (!std::isalnum((unsigned char)s[lo])) { lo++; continue; }
        if (!std::isalnum((unsigned char)s[hi])) { hi--; continue; }

        if (std::tolower((unsigned char)s[lo]) != std::tolower((unsigned char)s[hi])) return false;
        lo++; hi--;
    }
    return true;
}

